"""The course outline. Titles are mirrored in packages/shared/src/units.ts for display."""

UNITS: list[dict[str, str]] = [
    {"title": "Sounds and script", "focus": "the alphabet or writing system, the key sounds that don't exist in the learner's language, and how to read simple words"},
    {"title": "Greetings and introducing yourself", "focus": "hello, goodbye, my name is, how are you, polite vs informal address"},
    {"title": "I, you, he, she: pronouns and 'to be'", "focus": "personal pronouns and the verb 'to be' (or its equivalent), simple 'X is Y' sentences"},
    {"title": "Nouns: gender, plurals and articles", "focus": "grammatical gender or noun classes if any, making plurals, articles or counters"},
    {"title": "Present tense: everyday actions", "focus": "regular verbs in the present, how the verb changes by person, basic word order"},
    {"title": "Asking questions", "focus": "yes/no questions and question words: what, where, who, when, why, how much"},
    {"title": "Saying no", "focus": "negation of verbs and of 'to be', common negative words like never, nothing, nobody"},
    {"title": "Describing things: adjectives", "focus": "adjective position and agreement, colours, sizes, this/that"},
    {"title": "Numbers, time and dates", "focus": "numbers 1 to 100, telling the time, days of the week"},
    {"title": "The past: what happened", "focus": "the main past tense, common irregular past forms, time words like yesterday"},
    {"title": "The future and plans", "focus": "how to talk about the future and intentions, tomorrow, next week"},
    {"title": "Real conversation: at a shop and asking the way", "focus": "putting it together: polite requests, prices, directions, useful fixed phrases"},
]
